  put<T extends ApiData = ApiData, R extends ResponseType = 'json'>(url: string, body?: any, config?: BodyMethodConfig<R>): Promise<FlatResponseData<ResponseData, MappedType<R, T>>>;
  delete<T extends ApiData = ApiData, R extends ResponseType = 'json'>(url: string, config?: SimpleMethodConfig<R>): Promise<FlatResponseData<ResponseData, MappedType<R, T>>>;
  patch<T extends ApiData = ApiData, R extends ResponseType = 'json'>(url: string, body?: any, config?: BodyMethodConfig<R>): Promise<FlatResponseData<ResponseData, MappedType<R, T>>>;
